contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: sends arbitrary amount to c and verifies invariants
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance to forward");

        // record owner before
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        // record c balance before (should be zero for fresh instance, but allow generality)
        uint beforeCBal = address(c).balance;

        // perform the state-changing call on c, forwarding 'amount' wei
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable state after
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint afterCBal = address(c).balance;

        // General rule: owner never changes and c holds no Ether after go
        assert(afterOwner == beforeOwner && afterCBal == 0);
    }

    // allow receiving refunds/transfers if needed
    receive() external payable {}
}

